questionvariables.text:
/* Randomising bearings */
obsBoatAng:rand_with_step(110,160,5);
obsLightAng:rand_with_step(200,250,5);
boatLightAng:rand_with_step(280,330,5);

/* Randomising distances */
obsLightDist:rand(10)+11;

/* Solutions */

tans1:boatLightAng-180;

tans2:tans1-(obsLightAng-180);

tans3:obsLightDist*(sin(tans2*%pi/180)/sin((180+obsBoatAng-boatLightAng)*%pi/180));

feedbackvariables.text:
/* Node 1: Check correctness */
/* Node 2: Worked solution */

/* Node 3: Check whether student found BLO or OLB */
node3_test: if float(ans1)=float(tans2) or float(ans1)=float(360-tans2) then 1 else 0;

/* Node 4: Measuring bearing counter-clockwise */
node4_test: if float(ans1)=float(540-boatLightAng) then 1 else 0;

/* Node 5: Gives different bearing */
node5_test: if float(ans1)=float(obsBoatAng) or float(ans1)=float(obsLightAng) or float(ans1)=float(obsLightAng-180) or float(ans1)=float(boatLightAng) or float(ans1)=float(180+obsBoatAng) then 1 else 0;

/* Node 1: Check correct answer */
/* Node 2: Worked solution */

/* Node 3: ECF from (a) (2) */
ecf: ans1-(obsLightAng-180);

/* Node 4: Takes red angles as summing to 180 (1) */
node4_test: if float(ans2)=tans1-(360-obsLightAng) then 1 else 0;

/* Node 5: Finding OBL or LOB */
node5_test: if float(ans2)=float(180+obsBoatAng-boatLightAng) or float(ans2)=float(obsLightAng-obsBoatAng) then 1 else 0;

/* Node 1: Check correct answer */
/* Node 2: Worked solution */

/* Node 3: ECF from (b) (3) */
ecf:obsLightDist*(sin(ans2*%pi/180)/sin((180+obsBoatAng-boatLightAng)*%pi/180));

/* Node 4: Correct answer, seemingly incorrectly rounded (2) */
node4_test: if abs(ans3-tans3)<=1 then 1 else 0;

/* Node 5: Consistent answer, seemingly incorrectly rounded (2) */
node5_test: if abs(ans3-ecf)<=1 then 1 else 0;

/* Node 6: Uses sine rule incorrectly (2) */
node6_error: obsLightDist/(sin(ans2*%pi/180)/sin((180+obsBoatAng-boatLightAng)*%pi/180));

/* Node 7: Uses sine rule incorrectly and incorrectly rounded (1) */
node7_test: if abs(ans3-obsLightDist/(sin(ans2*%pi/180)/sin((180+obsBoatAng-boatLightAng)*%pi/180))) then 1 else 0;
